      typeof parcel.id !== 'string' || parcel.id.length === 0 ||
      typeof parcel.carrier !== 'string' || parcel.carrier.length === 0 ||
      typeof parcel.weight !== 'number' || !Number.isFinite(parcel.weight) || parcel.weight < 0) {
    throw new TypeError('invalid parcel');
  }
}

