'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['createParcelRegistry']);
assert.strictEqual(typeof api.createParcelRegistry, 'function');
const { createParcelRegistry } = api;

const initialA = { id: 'p2', carrier: 'Fast', weight: 5 };
const initialB = { id: 'p1', carrier: 'Slow', weight: 5 };
const registry = createParcelRegistry([initialA, initialB]);
initialA.carrier = 'MUTATED';
initialB.weight = 99;
assert.deepStrictEqual(registry.find('p2'), { id: 'p2', carrier: 'Fast', weight: 5 });
assert.deepStrictEqual(registry.find('p1'), { id: 'p1', carrier: 'Slow', weight: 5 });
assert.strictEqual(registry.find('absent'), null);
assert.throws(() => registry.find(1), TypeError);

const addedInput = { id: 'p3', carrier: 'Fast', weight: 1.5 };
const addedResult = registry.add(addedInput);
assert.deepStrictEqual(addedResult, { id: 'p3', carrier: 'Fast', weight: 1.5 });
assert.notStrictEqual(addedResult, addedInput);
addedInput.weight = 100;
addedResult.carrier = 'CHANGED';
assert.deepStrictEqual(registry.find('p3'), { id: 'p3', carrier: 'Fast', weight: 1.5 });
assert.throws(() => registry.add({ id: 'p3', carrier: 'Other', weight: 0 }), RangeError);

const listed = registry.list();
assert.deepStrictEqual(listed, [
  { id: 'p1', carrier: 'Slow', weight: 5 },
  { id: 'p2', carrier: 'Fast', weight: 5 },
  { id: 'p3', carrier: 'Fast', weight: 1.5 }
]);
listed[0].carrier = 'BROKEN';
assert.strictEqual(registry.find('p1').carrier, 'Slow');

assert.deepStrictEqual(
  registry.list({ carrier: 'Fast', sortBy: 'weight', direction: 'desc' }),
  [
    { id: 'p2', carrier: 'Fast', weight: 5 },
    { id: 'p3', carrier: 'Fast', weight: 1.5 }
  ]
);
assert.deepStrictEqual(
  registry.list({ sortBy: 'weight', direction: 'desc' }),
  [
    { id: 'p1', carrier: 'Slow', weight: 5 },
    { id: 'p2', carrier: 'Fast', weight: 5 },
    { id: 'p3', carrier: 'Fast', weight: 1.5 }
  ]
);
assert.deepStrictEqual(registry.list({ offset: 1, limit: 1 }), [
  { id: 'p2', carrier: 'Fast', weight: 5 }
]);
assert.deepStrictEqual(registry.list({ offset: 50 }), []);
assert.deepStrictEqual(registry.list({ limit: 0 }), []);

const changes = { carrier: 'Express', weight: 0 };
const updated = registry.update('p3', changes);
assert.deepStrictEqual(updated, { id: 'p3', carrier: 'Express', weight: 0 });
changes.carrier = 'MUTATED';
updated.weight = 50;
assert.deepStrictEqual(registry.find('p3'), { id: 'p3', carrier: 'Express', weight: 0 });
assert.strictEqual(registry.update('missing', { weight: 2 }), null);

for (const badParcel of [
  null,
  [],
  { id: '', carrier: 'C', weight: 0 },
  { id: 'x', carrier: '', weight: 0 },
  { id: 'x', carrier: 'C', weight: -1 },
  { id: 'x', carrier: 'C', weight: Infinity },
  { id: 'x', carrier: 'C', weight: NaN },
  { id: 1, carrier: 'C', weight: 0 }
]) {
  assert.throws(() => createParcelRegistry([badParcel]), TypeError);
}
assert.throws(() => createParcelRegistry([{ id: 'x', carrier: 'A', weight: 0 }, { id: 'x', carrier: 'B', weight: 1 }]), RangeError);
assert.throws(() => registry.add({ id: 'p4', carrier: 'C', weight: -0.1 }), TypeError);

for (const badOptions of [null, [], { sortBy: 'carrier' }, { direction: 'up' }, { offset: -1 }, { offset: 1.2 }, { limit: -1 }, { limit: 2.5 }, { carrier: 7 }]) {
  assert.throws(() => registry.list(badOptions), TypeError);
}
for (const badChanges of [null, [], {}, { id: 'new' }, { id: 'new', weight: 1 }, { carrier: '' }, { weight: -1 }, { weight: Infinity }]) {
  assert.throws(() => registry.update('p1', badChanges), TypeError);
}

const removed = registry.remove('p2');
assert.deepStrictEqual(removed, { id: 'p2', carrier: 'Fast', weight: 5 });
removed.carrier = 'MUTATED';
assert.strictEqual(registry.find('p2'), null);
assert.strictEqual(registry.remove('p2'), null);
assert.strictEqual(registry.clear(), 2);
assert.strictEqual(registry.clear(), 0);
assert.deepStrictEqual(registry.list(), []);

const empty = createParcelRegistry();
assert.deepStrictEqual(empty.list(), []);

